#include <cstdio>

int main() {
    char answers[8][4];
    int parsed = 0;
    for (int i = 0; i < 5; i++) {
        if (std::scanf("%3s", answers[i]) != 1) return 1;
        parsed++;
    }
    if (parsed != 5) return 1;
    char extra;
    if (std::scanf(" %c", &extra) != EOF) return 1;
    const char key[5] = {'B', 'A', 'C', 'B', 'C'};
    int score = 0;
    for (int i = 0; i < 5; i++) {
        if (answers[i][0] != 'A' && answers[i][0] != 'B' && answers[i][0] != 'C') return 1;
        if (answers[i][1] != '\0') return 1;
        if (answers[i][0] == key[i]) score++;
    }
    const char* level = score == 5 ? "expert" : (score >= 3 ? "solid" : "review");
    std::printf("score=%d/5 level=%s\n", score, level);
    return 0;
}

