private.reference_solution:
#include <cstdio>
#include <thread>
#include <vector>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 100) return 1;
    std::vector<int> scores;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (std::scanf("%d", &value) != 1) return 1;
        if (value < 0 || value > 100) return 1;
        scores.push_back(value);
    }
    long long sums[2] = {0, 0};
    int passes[2] = {0, 0};
    int half = n / 2;
    std::thread workers[2] = {
        std::thread([&scores, half, &sums, &passes]() {
            for (int i = 0; i < half; i++) {
                sums[0] += scores[static_cast<std::size_t>(i)];
                if (scores[static_cast<std::size_t>(i)] >= 60) passes[0]++;
            }
        }),
        std::thread([&scores, half, n, &sums, &passes]() {
            for (int i = half; i < n; i++) {
                sums[1] += scores[static_cast<std::size_t>(i)];
                if (scores[static_cast<std::size_t>(i)] >= 60) passes[1]++;
            }
        }),
    };
    workers[0].join();
    workers[1].join();
    double average = static_cast<double>(sums[0] + sums[1]) / n;
    std::printf("count=%d pass=%d average=%.2f\n", n, passes[0] + passes[1], average);
    return 0;
}
